// redux/reducer.js
import { ADD_TASK,DELETE_TASK,COMPLETE_TASK} from "../action-creators";

const initialState = {
  tasks: []
};
let inProgress=true;

const taskReducer = (state = initialState, action) => {
  switch (action.type) {
    case ADD_TASK:
      return { ...state, tasks: [...state.tasks, action.payload] };
    case DELETE_TASK:
      return {
        ...state,
        tasks: state.tasks.filter(task => task.id !== action.payload)
      };
    case COMPLETE_TASK:
      return {
        ...state,
        tasks: state.tasks.map(task =>
          task.id === action.payload ? { ...task, inProgress: false  } : task
        )
      };
      
    default:
      return state;
  }
};

export default taskReducer;
